head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[searchbox > P > showPlaceHolderOnReadOnly]<br/>SearchBox 컴포넌트가 readOnly 또는 disabled 상태일 때 placeholder 를 표시할지 설정합니다.",
    "validation" : [
        "readOnly=true 또는 disabled=true 이고 placeholder 속성이 설정된 경우에 동작합니다.",
        "true 설정 시 컴포넌트가 disabled 또는 readonly 상태일때 PlaceHolder 텍스트를 표시합니다.",
        "false (default) 설정 시 readOnly 또는 disabled 상태에서 placeholder 를 표시하지 않습니다.",
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 라벨 생성 (target1: disabled, target2: readOnly)
    $c.gcm.createLabel('label="target1 : disabled=true, placeholder=\'disabled=true 상태\'"', '', 'label1');
    $c.gcm.createLabel('label="target2 : readOnly=true, placeholder=\'readOnly=true 상태\'"', '', 'label2');

    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    if (typeof target2 !== 'undefined') {
        target2.remove();
    }

    // target1 : disabled=true 조건
    let properties = {
        placeholder : "disabled=true 상태",
        disabled : true,
        showPlaceHolderOnReadOnly : con_showPlaceHolderOnReadOnly.getText(),
    }

    // target2 : readOnly=true 조건
    let properties2 = {
        placeholder : "readOnly=true 상태",
        readOnly : true,
        showPlaceHolderOnReadOnly : con_showPlaceHolderOnReadOnly.getText(),
    }

    let cList = $c.gcm.createCList(properties);
    let cList2 = $c.gcm.createCList(properties2);

    await $c.gcm.createBasicSearchBox(cList, '', 'target1');
    await $c.gcm.createBasicSearchBox(cList2, '', 'target2');
};



// placeholder 속성 확인
scwin.btn_getPlaceholder_onclick = function (e) {
    // searchbox 내부 input 의 DOM placeholder 속성 확인
    let elem1 = target1.input.render;
    let elem2 = target2.input.render;

    let ph1 = elem1 ? (elem1.getAttribute('placeholder') || "") : "";
    let ph2 = elem2 ? (elem2.getAttribute('placeholder') || "") : "";

    wf_body_bottom.getObj("scwin").setReturnValue("target1 (disabled=true) placeholder : '" + ph1 + "'");
    wf_body_bottom.getObj("scwin").setReturnValue("target2 (readOnly=true) placeholder : '" + ph2 + "'");
};
